package com.paymentplatform.api_gateway.security;
import org.springframework.context.annotation.*;import org.springframework.boot.context.properties.*;import org.springframework.web.cors.*;import java.net.URI;import java.util.*;
@Configuration(proxyBeanMethods=false) @EnableConfigurationProperties(GatewayCors.Settings.class) public class GatewayCors {
 @ConfigurationProperties("boodoo.gateway") public record Settings(List<String> allowedOrigins){public Settings{allowedOrigins=allowedOrigins==null?List.of():allowedOrigins.stream().map(String::strip).filter(s->!s.isEmpty()).toList();for(String value:allowedOrigins){var uri=URI.create(value);if(!("http".equals(uri.getScheme())||"https".equals(uri.getScheme()))||uri.getHost()==null||uri.getUserInfo()!=null||uri.getQuery()!=null||uri.getFragment()!=null||!uri.getPath().isEmpty())throw new IllegalArgumentException("CORS entries must be explicit HTTP(S) origins without wildcard or path");}}}
 @Bean CorsConfigurationSource corsConfigurationSource(Settings settings){var config=new CorsConfiguration();config.setAllowedOrigins(settings.allowedOrigins());config.setAllowedMethods(List.of("GET","POST","PATCH","OPTIONS"));config.setAllowedHeaders(List.of("Authorization","Content-Type","Idempotency-Key","If-Match","If-None-Match"));config.setExposedHeaders(List.of("Location","ETag","Idempotency-Replayed","Retry-After"));config.setAllowCredentials(false);config.setMaxAge(3600L);var source=new UrlBasedCorsConfigurationSource();source.registerCorsConfiguration("/v1/**",config);return source;}
}
